(()=>{'use strict';
 const money=n=>(n/100).toLocaleString('ru-RU')+' ₽',node=(tag,text)=>{const n=document.createElement(tag);n.textContent=text;return n;};
 const id=()=>crypto.randomUUID();
 async function api(path,body){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const r=await fetch('/api/admin/workforce/'+path,{cache:'no-store',signal:controller.signal,...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw Object.assign(Error(d.error),d);return d;}catch(e){if(e.name==='AbortError'||e instanceof TypeError)throw Error('Нет подтверждения сервера. Повторите действие: запись не продублируется.');throw e;}finally{clearTimeout(timer);}}
 function modal(title){const d=document.createElement('dialog');d.className='day-desk-dialog';const h=node('h2',title),body=node('div',''),error=node('p',''),close=node('button','Закрыть');error.className='work-error';error.setAttribute('role','status');close.type='button';close.onclick=()=>d.close();d.append(h,body,error,close);document.body.append(d);d.onclose=()=>d.remove();d.addEventListener('cancel',e=>{if(close.disabled)e.preventDefault();});d.showModal();return {d,body,error,close};}
 function amount(body,label,value,negative=false){const l=node('label',label),input=document.createElement('input');input.type='text';input.inputMode='decimal';input.required=true;if(value!==undefined)input.value=String(value/100);l.append(input);body.append(l);queueMicrotask(()=>input.focus());return ()=>{const s=input.value.trim().replace(',','.');if(!(negative?/^-?\d+(\.\d{1,2})?$/:/^\d+(\.\d{1,2})?$/).test(s))throw Error('Укажите сумму в рублях, например 1500 или 1500,50.');const n=Math.round(Number(s)*100);if(!Number.isSafeInteger(n)||Math.abs(n)>100000000)throw Error('Проверьте сумму.');return n;};}
 function saveButton(m,label,fn){const b=node('button',label);b.type='button';b.className='primary';m.body.append(b);b.onclick=async()=>{if(b.disabled)return;b.disabled=true;m.close.disabled=true;m.error.textContent='';try{await fn();}catch(e){m.error.textContent=e.message||'Нет связи. Повторите действие.';}finally{b.disabled=false;m.close.disabled=false;}};return b;}
 async function start(userId){const current=await api('current');if(current.desk?.enabled&&!current.desk.canStart)throw Error('Начать новую смену можно с 08:00 по Москве.');const body={requestId:id(),...(userId?{userId}:{})};if(current.desk?.enabled&&current.desk.needsOpening){return new Promise(resolve=>{const m=modal('Начать рабочий день');m.body.append(node('p','Укажите, сколько наличных сейчас в кассе. Это остаток для размена, он не входит в выручку и зарплату. Можно указать 0.'));const read=amount(m.body,'Наличные на начало, ₽',current.desk.suggestedCashCents??undefined);if(current.desk.suggestedCashCents!==undefined)m.body.append(node('p','Предложен остаток прошлого дня. Пересчитайте наличные и подтвердите сумму.'));let sent=false;saveButton(m,'Начать работу',async()=>{if(!sent){body.cashStartCents=read();sent=true;m.body.querySelector('input').disabled=true;}await api('start',body);document.dispatchEvent(new Event('station-updated'));m.d.close();resolve(true);});m.d.addEventListener('close',()=>resolve(false));});}await api('start',body);document.dispatchEvent(new Event('station-updated'));return true;}
 async function summary(day){
  const s=await api('day-summary'+(day?'?day='+encodeURIComponent(day):'')),m=modal('Итог смены · '+s.day),finance=s.finance||s.calculation?.revenue||{};
  if(!s.shift){m.body.append(node('p','Рабочий день ещё не начат. Нажмите «Я на смене».'));return;}
  m.body.append(node('p','Начальный остаток: '+money(s.shift.cash_start_cents)));
  const ledger=s.cashLedger;
  if(ledger){m.body.append(node('p','Касса: начало '+money(ledger.openingCents)+' · прокат '+money(ledger.rentalCents)+' · кафе '+money(ledger.cafeCents)+' · возвраты '+money(-ledger.refundsCents)+' · изъятия '+money(-ledger.withdrawalsCents)+' · внесения '+money(ledger.depositsCents)+' · поправки '+money(ledger.adjustmentsCents)+' · выплаты '+money(-ledger.payrollCents)+' · остаток '+money(ledger.balanceCents)));if(ledger.unknownCount)m.body.append(node('p','Есть оплаты без указанного способа: '+ledger.unknownCount+'.'));}
  const rows=Array.isArray(s.withdrawals)?s.withdrawals:(s.withdrawals?.items||[]);if(rows.length)m.body.append(node('p','Изъятия: '+money(rows.filter(x=>!x.voided_at).reduce((n,x)=>n+x.amount_cents,0))+' · не вычитаются из зарегистрированной выручки.'));
  if(s.shift.closed_at){if(s.automaticClose)m.body.append(node('p','День закрыт автоматически в 07:30 по Москве. Начисление за забытые смены ограничено 02:00. Выручка — по зарегистрированным продажам, без ручной сверки.'));m.body.append(node('p','Зарегистрированная выручка: '+money(finance.cents??s.registeredCents??s.shift.total_revenue_cents)),node('p','Итог сохранён: '+money(s.shift.total_revenue_cents)));if(finance.declared_cents!==undefined)m.body.append(node('p','Заявлено при закрытии: '+money(finance.declared_cents)));if(finance.variance_cents)m.body.append(node('p','Разница: '+money(finance.variance_cents)+'. Не влияет на начисления.'));m.body.append(node('p','Работа после сохранения итога учитывается отдельно при следующей сверке.'));
   const employees=s.employees||s.calculation?.employees||[],origins=new Map();if(employees.length){m.body.append(node('h3','Начисления сотрудников'));for(const e of employees){m.body.append(node('p',(e.name||String(e.user_id))+' — начислено '+money(e.salary_cents??e.salaryCents??0)+(e.remaining_cents!==undefined?' · осталось '+money(e.remaining_cents):'')+(e.review_required?' · требуется проверка':'')));for(const origin of e.origins||[]){const date=origin.day||origin.origin_day||origin.date||'Источник не указан';if(!origins.has(date))origins.set(date,[]);origins.get(date).push({name:e.name||String(e.user_id),cents:origin.salary_cents??origin.amount_cents??origin.cents??0});}}}
   if(origins.size){m.body.append(node('h3','Начисления по дате происхождения'));for(const [date,items] of origins){m.body.append(node('h3',date));for(const item of items)m.body.append(node('p',item.name+' — '+money(item.cents)));}}
   const carried=s.calculation?.carried_work||[];if(carried.length&&!origins.size){m.body.append(node('h3','Зарплата из предыдущих дней'));for(const carry of carried){m.body.append(node('h3',carry.day||carry.origin_day||'дата не указана'));for(const e of carry.employees||[])m.body.append(node('p',(e.name||String(e.user_id))+' — '+money(e.salary_cents||e.salaryCents||0)));}}
   const slot=node('div','');m.body.append(slot);if(window.STARTPrint)window.STARTPrint.mountReport(slot,{shiftId:s.shift.id,preview:true,closed:true});return;}
  m.body.append(node('p','Выручка кафе и проката с учётом возвратов. Остаток на начало и изъятия сюда не входят.'));
  const useCashCount=!!ledger&&!ledger.unknownCount&&!s.shift.closed_at&&ledger.shift?.id===s.shift.id&&!ledger.shift.closed;
  let readDeclared,readCash,readCashless;
  if(useCashCount){m.body.append(node('p','Расчётный остаток для ориентира: '+money(ledger.balanceCents)+' · наличные нужно пересчитать.'));readCash=amount(m.body,'Наличные по пересчёту, ₽');readCashless=amount(m.body,'Безнал за вычетом возвратов, ₽',undefined,true);}
  else readDeclared=amount(m.body,'Заявленная выручка за день, ₽',s.registeredCents??finance.cents,true);
  if(ledger?.unknownCount)m.body.append(node('p','Для закрытия доступен ввод общей заявленной выручки: есть оплаты без указанного способа.'));
  saveButton(m,'Проверить итог',async()=>{
   const body=useCashCount?{shiftId:s.shift.id,cashEndCents:readCash(),cashlessCents:readCashless()}:{shiftId:s.shift.id,totalRevenueCents:readDeclared()};
   const p=await api('preview',body),c=p.calculation||s.calculation||{},revenue=c.revenue||s.finance||{},registered=revenue.cents??s.registeredCents??revenue.registered_cents,declared=revenue.declared_cents??(body.totalRevenueCents??revenue.cents),variance=revenue.variance_cents??(declared-registered);
   const v=modal('Проверить начисления');v.body.append(node('p','Зарегистрированная выручка: '+money(registered)));if(declared!==undefined)v.body.append(node('p',(useCashCount?'По пересчёту':'Заявленная выручка')+': '+money(declared)));if(variance)v.body.append(node('p','Разница: '+money(variance)+'. Не влияет на начисления.'));
   const carryByUser=new Map();for(const carry of c.carried_work||[]){for(const e of carry.employees||[]){const key=e.user_id??e.userId;carryByUser.set(key,(carryByUser.get(key)||0)+(e.salary_cents||e.salaryCents||0));}}
   for(const e of c.employees||[]){const carry=carryByUser.get(e.user_id)||0;v.body.append(node('p',e.name+' — за день '+money(Math.max(0,e.salary_cents-carry))+(carry?' · всего к выплате '+money(e.salary_cents):'')+(e.active?' · ещё на смене':'')));}
   for(const carry of c.carried_work||[]){const date=carry.day||carry.origin_day||'Исходный день';v.body.append(node('h3','Перенос зарплаты · '+date));for(const e of carry.employees||[])v.body.append(node('p',(e.name||String(e.user_id))+' — '+money(e.salary_cents||e.salaryCents||0)));}
   const payload={...body,previewHash:p.previewHash,requestId:id()},b=saveButton(v,'Подвести и сохранить итог дня',async()=>{await api('day-close',payload);v.d.close();m.d.close();document.dispatchEvent(new Event('station-updated'));await summary(s.day);});
   if(!c.employees?.length||c.unallocated_bonus_cents){b.disabled=true;v.error.textContent='Проверьте, что есть сотрудники и все продажи относятся к их рабочему времени.';}else if(c.employees.some(e=>e.active)){b.disabled=true;v.error.textContent='Есть активная смена. Просмотрите расчёт; для закрытия завершите смены сотрудников.';}
  });
 }
 async function withdrawal(){const s=await api('withdrawal-context');if(!s.shift)throw Error('Рабочий день ещё ни разу не открывали. Сначала нажмите «Я на смене».');const m=modal('Забрать деньги из кассы');m.body.append(node('p','Рабочий день: '+s.shift.day.split('-').reverse().join('.')+(s.shift.closed_at?' · итог уже сохранён. Изъятие запишется отдельно, без изменения выручки и зарплаты.':'. Изъятие не уменьшает выручку и зарплату.')));const read=amount(m.body,'Сумма изъятия, ₽'),l=node('label','Комментарий · необязательно'),input=document.createElement('input');l.append(input);m.body.append(l);let payload;saveButton(m,'Сохранить изъятие',async()=>{if(!payload){const n=read();if(n<=0)throw Error('Сумма должна быть больше нуля.');payload={requestId:id(),shiftId:s.shift.id,amountCents:n,comment:input.value};m.body.querySelectorAll('input').forEach(x=>x.disabled=true);}await api('withdrawal',payload);m.d.close();document.dispatchEvent(new Event('station-updated'));});}
 async function opening(){const s=await api('day-summary');if(!s.shift||s.shift.closed_at)throw Error('Исправить остаток можно до сохранения итога дня.');const m=modal('Начальный остаток'),read=amount(m.body,'Наличные на начало, ₽',s.shift.cash_start_cents);saveButton(m,'Сохранить остаток',async()=>{await api('opening-balance',{shiftId:s.shift.id,expectedCashStartCents:s.shift.cash_start_cents,cashStartCents:read()});m.d.close();});}
 function last(){const m=modal('Вы последний завершили смену');m.body.append(node('p','Можно сейчас проверить выручку и начисления за день.'));m.close.textContent='Позже';saveButton(m,'Подвести и сохранить итог дня',async()=>{m.d.close();await summary();});}
 async function openCash(){
  const current=await api('current'),desk=current.desk;
  if(!desk?.enabled)throw Error('Упрощённый рабочий день не включён.');
  if(!desk.needsOpening)throw Error(desk.closed?'Итог этого дня уже сохранён. Движение наличных остаётся доступно.':'Касса на сегодня уже открыта.');
  if(!desk.canStart)throw Error('Открыть кассу можно с 08:00 по Москве.');
  const m=modal('Открыть кассу');m.body.append(node('p','Укажите наличные на начало дня. Открытие кассы не отмечает приход на смену и не начисляет зарплату.'));
  const read=amount(m.body,'Наличные в кассе, ₽',desk.suggestedCashCents??0);let payload;
  return new Promise(resolve=>{m.d.addEventListener('close',()=>resolve(false));saveButton(m,'Открыть кассу',async()=>{if(!payload){payload={requestId:id(),day:desk.day,cashStartCents:read()};m.body.querySelector('input').disabled=true;}await api('cash-open',payload);document.dispatchEvent(new Event('station-updated'));resolve(true);m.d.close();});});
 }
 window.STARTWork={start,summary,withdrawal,opening,last,openCash};
})();
